    ok(q('.detail .hv-big .hv-cruce') && /Sábado 14 nov/.test(q('.detail .hv-cruce').textContent) && /1 historia/.test(q('.detail .hv-cruce').textContent), 'el velo');
    ok(q('.detail .hv-dn.cruce'), 'el rótulo en acento');
