    igual(r4.parada, 'cancelada', 'cancelar');
    ok(r4.subidas < 30 && porNombre()['Corta'].files.length === r4.subidas, 'lo subido al cancelar');
    ok(!q('.cpprog'), 'la barra sigue');
    igual((await M.informeArchivos()).huerfanos, [], 'huérfanos al cancelar');
