    // historia: el anillo y borrar la carpeta la deja en la raíz
    const hid = M.hs.anadir(`${MES}-21`); M._in.S.historias.find(x => x.id === hid).libre = { slides: { r0: { els: [{ id: 'e1', t: 'foto', src: e }] } } }; M._in.save();
