  const otroTablero = () => M.init({ client: CLIENTE2, clientName: NOMBRE2, month: MES, slots: [{ id: 'v-otro', name: 'Foto 1.1', type: 'Foto', date: '2026-11-10T12:00:00.000+01:00' }], past: [], force: true });
