      await M.open(r.key);
      { const e = slot('r2').estado; igual({ v: e.v, fecha: e.fecha }, { v: 'programado', fecha: slot('r2').date }, 'una Programada de antes no tomó su fecha al abrir'); }
      const dbs = W.indexedDB.databases ? await W.indexedDB.databases() : [];
