      accion('bandeja'); accion('bandeja'); dondeX(ts(), fotoE(eu), 'el editor, al cerrar y abrir su bandeja');
      M.libre.cerrar(); await editorConBandeja('r1'); dondeX(ts(), fotoE(eu), 'el editor, al volver a abrirlo');
