    const sin = r => json(Object.assign({}, r, { savedAt: 0, at: 0 }));   // sin la hora de guardado
    const bd0 = sin(await M._in.idbGet('bandejas', CLIENTE)), tb0 = sin(await M._in.idbGet('boards', clave)), h0 = json(M._test.hist());
