      ok(toastCon(/^Falta la foto de la diapositiva 2: suéltala en ella o elígela en la bandeja\./), 'sin el aviso de la foto que falta');
      igual(dzFoto(1).src, null, 'la diapositiva sin foto no abre con la «Foto» vacía');
