    await uEsperaMarcas({ 'u3-a.jpg': 'p0', 'u3-c.jpg': 'p0', 'u3-b.jpg': 'r', 'u3-reel.jpg': 'p0', 'u3-hueco.jpg': 'p0', 'u3-cancelada.jpg': 'r', 'u3-hist.jpg': '' }, 'las marcas');
