        ok(q('.detail .pbody > .phead'), `${id}: la cabecera no va en el cuerpo de la ventana`);
        ok(R('.detail .stage').top - card.top < 40, `${id}: la foto no empieza arriba del todo (${Math.round(R('.detail .stage').top - card.top)} px)`);
