      const hojaC = D.getElementById('mesa-cal-css');
      ok(hojaC && ['--cx-r', '--cx-hoy', '--cx-nav', '--cx-otro', '--cx-gap', '--cx-casilla'].every(k => hojaC.textContent.includes('var(' + k)), 'el de las publicaciones no usa los tokens compartidos');
