      igual([nom(eon), tit(eon), bg(eon)], ['R3 Uno', 'Bandeja / R3 Uno', acc], 'en el editor');
      ok(q('.lb-tray .lb-trv') && !q('.lb-trh b'), 'en el editor: sin ← o con la ruta en texto');
