      igual((await M.material.ver()).map(x => x.nombre + '·' + x.tipo + (x.padre ? '·hijo' : '')), ['Revisar baterías·ambas', 'Luz de vídeo·video', 'Cuerpo·ambas', 'Foco·ambas', 'Pie del foco·ambas·hijo', 'Disparador·foto', 'Micro·video'], 'MESA.material.ver');
