      ok(!/\.pp-ma-w:hover \.pp-ma-c/.test(reglas), 'la ficha se ensancha al pasar');
      ok(/prefers-reduced-motion[\s\S]*\.pp-hj-fin:active[\s\S]*\.pp-ma-x:active/.test(reglas), '«Reducir movimiento» no cubre las pulsaciones nuevas');
