      const cs = e => W.getComputedStyle(e), ink = () => rgbDe(cs(q('#mesa')).getPropertyValue('--ty-ses-ink').trim()).join(), red = () => rgbDe(cs(q('#mesa')).getPropertyValue('--red').trim()).join();
      const fila = (id, sel) => q(`${sel}[data-tid="${id}"]`);
