  async function ifMes(dir) { const b = q(`.side > .cal [data-cal="${dir}"]`); ok(b && !b.disabled, 'no hay ' + dir); if (b) { b.click(); await espera(60); } }
  const ifMesCal = () => (q('.side > .cal .cmes') || {}).textContent || '';
