      igual([...cf.querySelectorAll('.if-f i')].map(i => i.className), ['sube', 'sin', 'baja', 'igual'], 'el color de cada cambio');
      igual(cf.querySelector('.if-f b').title, '11.200', 'la cifra exacta en el title');
